import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ADMIN_DASHBOARD_REFRESH_EVENT, adminApi } from '../services/api';
import { normalizeCollectionResponse } from '../lib/normalizeCollectionResponse';

const getRequestErrorMessage = (err, fallbackError) => {
  return (
    err?.response?.data?.message ||
    err?.message ||
    fallbackError
  );
};

export const useAdminDashboardData = () => {
  const [stats, setStats] = useState(null);
  const [pendingNotes, setPendingNotes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const loadingRef = useRef(false);

  const loadData = useCallback(async () => {
    if (loadingRef.current) {
      return;
    }

    loadingRef.current = true;
    setLoading(true);
    setError('');

    try {
      const [statsResult, pendingResult] = await Promise.allSettled([
        adminApi.dashboardStats(),
        adminApi.pendingNotes(),
      ]);

      const nextErrors = [];

      if (statsResult.status === 'fulfilled') {
        const statsRes = statsResult.value;
        const normalizedStats = statsRes?.kpis || statsRes?.charts ? statsRes : statsRes?.data || {};
        setStats(normalizedStats);
      } else {
        setStats(null);
        nextErrors.push(getRequestErrorMessage(statsResult.reason, 'Impossible de charger les statistiques admin.'));
      }

      if (pendingResult.status === 'fulfilled') {
        const pendingRes = pendingResult.value;
        const normalizedPending = Array.isArray(pendingRes)
          ? pendingRes
          : pendingRes?.data || pendingRes?.results || [];
        setPendingNotes(normalizedPending);
      } else {
        setPendingNotes([]);
        nextErrors.push(getRequestErrorMessage(pendingResult.reason, 'Impossible de charger les notes en attente.'));
      }

      if (nextErrors.length) {
        setError(nextErrors.join(' '));
      }
    } finally {
      loadingRef.current = false;
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  useEffect(() => {
    const handleRefresh = () => {
      loadData();
    };

    window.addEventListener(ADMIN_DASHBOARD_REFRESH_EVENT, handleRefresh);

    return () => {
      window.removeEventListener(ADMIN_DASHBOARD_REFRESH_EVENT, handleRefresh);
    };
  }, [loadData]);

  return {
    stats,
    pendingNotes,
    loading,
    error,
    reload: loadData,
  };
};

export const useAdminResourceList = (loader, fallbackError) => {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const loaderRef = useRef(loader);

  useEffect(() => {
    loaderRef.current = loader;
  }, [loader]);

  const loadData = useCallback(async () => {
    setLoading(true);
    setError('');

    try {
      const response = await loaderRef.current();
      setItems(normalizeCollectionResponse(response));
    } catch (err) {
      console.error('Admin resource request failed:', err);
      setItems([]);
      setError(getRequestErrorMessage(err, fallbackError));
    } finally {
      setLoading(false);
    }
  }, [fallbackError]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  return useMemo(
    () => ({
      items,
      loading,
      error,
      reload: loadData,
    }),
    [error, items, loadData, loading]
  );
};
